 [220168]={enName="Triple-Brewed Molten Lager",en="An elixir of fire, created with steady hands and an unsteady mind...",it="Un elisir di fuoco, creato con mani ferme e mente instabile…"},
 [220169]={enName="Symbol of Faith",en="A symbol of faith, gifted from one with newly discovered purpose...",it="Un simbolo di fede, donato da qualcuno che ha appena trovato uno scopo…"},
