 [220345]={enName="Sanguine Sorcery",en="Outlines a variety of powerful blood rituals. A controversial addition to any library's collection.",it="Descrive diversi potenti rituali del sangue. Un’aggiunta controversa alla collezione di qualsiasi biblioteca."},
 [220346]={enName="Legends of the Tidesages",en="Covered in illegible notes and diagrams scrawled by an unsteady hand. It could still be a decent addition to any library's collection.",it="Ricoperto di appunti e diagrammi illeggibili tracciati da una mano tremante. Potrebbe comunque essere una discreta aggiunta a qualsiasi biblioteca."},
 [220347]={enName="The Liminal and the Arcane",en="The words swim on the page, defying attempts to read them. A puzzling addition to any library's collection.",it="Le parole si muovono sulla pagina, sfuggendo a ogni tentativo di lettura. Un’aggiunta enigmatica alla collezione di qualsiasi biblioteca."},
 [220348]={enName="Everyday Etiquette",en="A guide to the role of elementary magic in polite Highborne society.  A fine addition to any library's collection.",it="Una guida al ruolo della magia elementale nella società cortese degli Altomaghi. Un’ottima aggiunta alla collezione di qualsiasi biblioteca."},
 [220349]={enName="Stonewrought Design",en="Sturdy architectural techniques capable of withstanding all but the most cataclysmic disasters.  A fine addition to any library's collection.",it="Tecniche architettoniche robuste, capaci di resistere a tutto tranne che ai disastri più catastrofici. Un’ottima aggiunta alla collezione di qualsiasi biblioteca."},
 [220350]={enName="Venomous Journeys",en="Notes on the mind-altering properties of various toxins and venoms.  A fine addition to any library's collection.",it="Appunti sulle proprietà che alterano la mente di diverse tossine e diversi veleni. Un’ottima aggiunta alla collezione di qualsiasi biblioteca."},
 [220351]={enName="Murky Air Sapta",en="A murky concoction. Strange ill-gotten influence taints the otherwise recognizable magic.",it="Una mistura torbida. Una strana influenza ottenuta illecitamente contamina la magia, altrimenti riconoscibile."},
 [220352]={enName="A Mind of Metal",en="Dwarven techniques for applying magic to metallurgy, strip-mining and heavy industry.  An informative, if bleak, addition to any library's collection.",it="Tecniche dei nani per applicare la magia alla metallurgia, all’estrazione mineraria intensiva e all’industria pesante. Un’aggiunta istruttiva, seppur cupa, alla collezione di qualsiasi biblioteca."},
 [220353]={enName="Conjurer's Codex",en="A pre-war collection of spells and arcane theories that have largely fallen out of modern use.  A fine addition to any library's collection.",it="Una raccolta prebellica di incantesimi e teorie arcane, ormai in gran parte caduti in disuso. Un’ottima aggiunta alla collezione di qualsiasi biblioteca."},
