 [255727]={enName="Manual: Superior Poultice",en="Teaches you how to make a Superior Poultice.",it="Ti insegna a preparare un Cataplasma superiore."},
 [255728]={enName="Manual: Potent Anti-Venom",en="Teaches you how to make a Potent Anti-Venom.",it="Ti insegna a preparare un antiveleno potente."},
 [255729]={enName="Manual: Major Healing Potion",en="Teaches you how to make a Major Healing Potion.",it="Ti insegna a creare una Pozione Maggiore di Cura."},
 [255730]={enName="Manual: Surgical Tourniquet",en="Teaches you how to make a Surgical Tourniquet.",it="Ti insegna a preparare un Laccio emostatico chirurgico."},
 [255731]={enName="Manual: Powerful Poultice",en="Teaches you how to make a Powerful Poultice.",it="Ti insegna a preparare un cataplasma potente."},
 [255878]={enName="Tear of Theradras",en="It hums with power. You feel emboldened in your journey while holding this.",it="Vibra di potere. Mentre lo tieni in mano, ti senti più coraggioso durante il tuo viaggio."},
 [255945]={enName="Accursed Skull",en="An evil presence can be felt within.",it="Al suo interno si percepisce una presenza malvagia."},
 [256057]={enName="Draenethyst Crystal",en="An incredibly rare crystal that originated from another world. Its numerous uses have only just begun to be discovered.",it="Un cristallo incredibilmente raro, proveniente da un altro mondo. Si è appena iniziato a scoprirne i numerosi usi."},
 [257126]={enName="Heart of the Obliterator",en="It has the glow of life, but no warmth.",it="Ha il bagliore della vita, ma non emana calore."},
 [257348]={enName="Essence of Innovation",en="Contains the very spark of creativity.",it="Contiene la scintilla stessa della creatività."},
 [257685]={enName="Totem Tote",en="Packed to the brim with totems used by the centaur as currency. Delivering this to one of the rivaling clans is sure to earn their favor.",it="Colmo fino all'orlo di totem usati dai centauri come valuta. Consegnarlo a uno dei clan rivali ti farà sicuramente guadagnare il loro favore."},
 [257808]={enName="Parcel of Mail",en="Letters and packages for delivery to Everlook.",it="Lettere e pacchi da consegnare a Everlook."},
 [257809]={enName="Parcel of Mail",en="Letters and packages for delivery to Mount Hyjal.",it="Lettere e pacchi da consegnare al Monte Hyjal."},
 [258296]={enName="Vial of Earth Song Water",en="A single vial of this mystical water can bring about a torrent of rainfall.",it="Una sola fiala di quest'acqua mistica può scatenare un torrente di pioggia."},
 [258526]={enName="Flight Log",en="The journal is filled with atmospheric weather and rocket staging information.",it="Il diario è pieno di informazioni meteorologiche e sulla preparazione dei razzi."},
 [258530]={enName="Lucky Lure",en="Covered in the guts of countless swamp fish",it="Ricoperto delle interiora di innumerevoli pesci di palude"},
 [258771]={enName="Al'Alketh Cultist's Ear",en="You can't help but wonder what the Nightclaw plan to do with all these ears?",it="Non puoi fare a meno di chiederti cosa intendano fare i Nightclaw con tutte queste orecchie."},
 [258774]={enName="Gimashi's Findings",en="The notes are written in multiple colors of ink, a sign of a long study.",it="Gli appunti sono scritti con inchiostro di diversi colori, segno di un lungo studio."},
 [259226]={enName="Spectral Iron Ore",en="Simply iron ore, though bound to the spirit realm.",it="Semplice minerale di ferro, benché legato al regno degli spiriti."},
 [259229]={enName="Vindael's Spectral Pickaxe",en="Reveals Ghostly Iron Deposits while in your inventory. Also serves as a regular mining pick!",it="Rivela i Giacimenti di Ferro Spettrale quando si trova nel tuo inventario. Serve anche come un normale piccone da minatore!"},
 [2598]={enName="Pattern: Red Linen Robe",en="Teaches you how to sew a Red Linen Robe.",it="Ti insegna a creare una Tonaca di Lino Rossa."},
 [259990]={enName="Tusk Ring",en="This was a troll's tusk ring. It was clearly well-loved once, but that was long ago.",it="Era un anello ricavato da una zanna di troll. Un tempo era chiaramente molto amato, ma è passato tanto tempo."},
 [2601]={enName="Pattern: Gray Woolen Robe",en="Teaches you how to sew a Gray Woolen Robe.",it="Ti insegna a creare una Tonaca di Lana Grigia."},
 [260167]={enName="Adventurer's Lost Boots",en="Inscribed on the boot tongue: ...16, 23...",it="Inciso sulla linguetta dello stivale: ...16, 23..."},
 [260236]={enName="Scribbled Directions to Sulfur Vents",en="A hastily-scrawled list of locations for prospecting.",it="Un elenco di luoghi da esplorare, scarabocchiato in fretta."},
 [260237]={enName="Virulent Blood of Agamaggan",en="Whether it is actually the blood of the fallen god is unclear, but what is certain is how eager it seems to escape the vial.",it="Non è chiaro se sia davvero il sangue del dio caduto, ma ciò che è certo è quanto sembri impaziente di sfuggire alla fiala."},
 [260244]={enName="Benevolent Bouquet",en="Do quilboar even like flowers?",it="Ai quilboar piacciono davvero i fiori?"},
 [260245]={enName="Vibrant Flower",en="Its beauty is a stark contrast from the gardens in which it grew.",it="La sua bellezza è in netto contrasto con i giardini in cui è cresciuto."},
 [260247]={enName="Forlorn Necklace",en="Once an enchanted necklace that sustained life in the gardens of Shen'dralas. Whatever magic it once contained has since been depleted.",it="Un tempo era una collana incantata che manteneva in vita i giardini di Shen'dralas. Qualunque magia contenesse si è ormai esaurita."},
 [260307]={enName="Hyjal Postal Satchel",en="Neither snow nor rain nor heat nor gloom of night...",it="Né neve né pioggia né caldo né tenebre della notte..."},
 [260347]={enName="Tattered Journal",en="Most of the pages are missing.",it="Manca la maggior parte delle pagine."},
 [260518]={enName="Azore's Transcription",en="Gimashi's findings on draenethyst; organized and edited for clarity.",it="Le scoperte di Gimashi sulla draenethyst, organizzate e rielaborate per maggiore chiarezza."},
 [260784]={enName="SAF-T Tabs",en="SAF-T brand tabs make it SAF to hand out dynamite to all your friends!",it="Le linguette di marca SAF-T rendono SAF distribuire dinamite a tutti i tuoi amici!"},
 [260792]={enName="SAF-T Dynamite",en="Easy to throw, and SAF-T too!",it="Facile da lanciare, e anche SAF-T!"},
 [260793]={enName="SAF-T Copper Bomb",en="SAF-T Brand bombs *almost* never blow up in your hands (or your paws!)",it="Le bombe di marca SAF-T *quasi* mai ti esplodono in mano (o tra le zampe!)"},
 [260796]={enName="No Slip SAF-T Padding",en="SAF-T Padding prevents those easy throwing accidents.",it="L'imbottitura SAF-T previene quegli incidenti dovuti ai lanci facili."},
 [260798]={enName="SAF-T Jumbo Dynamite",en="If it's easy to throw, it's not SAF-T!",it="Se è facile da lanciare, non è SAF-T!"},
 [260799]={enName="SAF-T Bell",en="Do you know where your Sheep is?! SAF-T Knows.",it="Sai dov'è la tua Pecora?! SAF-T lo sa."},
 [260800]={enName="Shafety Sheep",en="Guaranteed to blow up only where it's SAF!",it="Garantito: esplode solo dove è SAF!"},
 [260801]={enName="EZ-Thro Fireproof Fuse",en="Guaranteed not to burn!",it="Garantito che non brucia!"},
 [260803]={enName="EZ-Thro Grenade",en="Who needs safety when it's this easy to throw?",it="A chi serve la sicurezza quando è così facile da lanciare?"},
 [260804]={enName="SAF-T Casing",en="Extra padding for SAF-T!",it="Imbottitura extra per SAF-T!"},
 [260805]={enName="SAF-T Bomb",en="S. A. F. T. B. O. M. B. SAF-T. Bomb.",it="S. A. F. T. B. O. M. B. Bomba SAF-T."},
 [260806]={enName="Emergency Field Cloak",en="SAF-T means not getting caught.",it="SAF-T significa non farsi beccare."},
 [260808]={enName="EZ-Thro Tru-Trigger",en="EZ to use and almost never misfires!",it="Facile da usare e quasi mai fa cilecca!"},
 [260809]={enName="Tru-Trigger Frag Bomb",en="Tru-Trigger frags enemies, not in your hands.",it="Le schegge Tru-Trigger colpiscono i nemici, non le tue mani."},
 [260810]={enName="SAF-T Disposable Parachute",en="SAF-T in case you need to jump.",it="SAF-T nel caso in cui ti serva saltare."},
 [260811]={enName="Gnomish Army Knife",en="It's got everything: a spanner, a wrench, a hammer... even a mining pick.",it="Ha tutto: una chiave inglese, una chiave, un martello... persino un piccone da minatore."},
 [260813]={enName="SAF-T Tube",en="Prevents accidental oxygen exposure. That wouldn't be SAF.",it="Previene l'esposizione accidentale all'ossigeno. Quella non sarebbe SAF."},
 [260814]={enName="SAF-T Clever Dynamite",en="SAF-T isn't dense. It's clever!",it="SAF-T non è ottuso. È furbo!"},
 [260815]={enName="EZ-Thro Shell",en="Encase your explosives in EZ to Thro thorium-plated shells.",it="Racchiudi i tuoi esplosivi in gusci placcati al torio EZ to Thro."},
 [260816]={enName="EZ-Thro Thorium Grenade",en="Anyone can use grenades with EZ-Thro!",it="Chiunque può usare le granate con EZ-Thro!"},
 [260817]={enName="EZ-Thro Dark Bomb",en="So EZ, you can Thro it in the dark.",it="Così facile che puoi lanciarla al buio."},
 [260821]={enName="EZ and SAF Field Transporter: Mt. Hyjal",en="Not only combining Goblin and Gnome tech, but also combining plans from the EZ-Thro and SAF-T corporations. Who knows if this will even work?",it="Non solo unisce la tecnologia Goblin e Gnomica, ma anche i progetti delle aziende EZ-Thro e SAF-T. Chissà se funzionerà davvero?"},
 [260823]={enName="Dimensional Transporter - Mt. Hyjal",en="A dangerous amalgamation of Goblin and Gnome engineering techniques.",it="Una pericolosa amalgama di tecniche ingegneristiche Goblin e Gnomiche."},
 [260827]={enName="Stealthman 52",en="Used by real secret agents.",it="Usato dai veri agenti segreti."},
 [260828]={enName="SAF-T Nitro Boosts",en="Rocket to safety with SAF-T.",it="Raggiungi la sicurezza con un razzo SAF-T."},
 [260829]={enName="EZ-Thro Magnetic Displacer",en="EZ-Thro corporation not responsible for magnets preventing grenades from being thrown.",it="La EZ-Thro corporation non è responsabile se i magneti impediscono di lanciare le granate."},
 [260830]={enName="SAF-T Teleport",en="Teleport to SAF-T!",it="Teletrasportati a SAF-T!"},
 [260880]={enName="Air Construct Core",en="The glowing orb seems to be looking at you, following your movements with quiet curiosity.",it="La sfera luminosa sembra guardarti, seguendo i tuoi movimenti con tranquilla curiosità."},
 [260881]={enName="Crystallized Lightning",en="The surface of this object is smooth to the touch and makes the hair on the back of your neck stand up when you hold it.",it="La superficie di questo oggetto è liscia al tatto e ti fa rizzare i peli sulla nuca quando lo tieni in mano."},
 [260883]={enName="Enchanted Gyrozephyr",en="This object softly vibrates, constantly in a state of perpetual motion. If you try to hold it still, the force it exerts increases greatly in intensity.",it="Questo oggetto vibra leggermente, in uno stato di moto perpetuo. Se provi a tenerlo fermo, la forza che esercita aumenta notevolmente."},
 [262668]={enName="Wind-Infused Bough",en="Headless wind whistles a soft chill through the enchanted branches.",it="Il vento senza testa fischia un lieve brivido tra i rami incantati."},
 [262766]={enName="Reins of the Pack Kodo",en="Teaches you how to summon this mount.",it="Insegna a evocare questa cavalcatura."},
 [262801]={enName="Barkskin Satchel",en="Stitched with mottled but sturdy leather.",it="Cucito con pelle screziata ma resistente."},
 [262887]={enName="Sealed Apprentice's Writ",en="A pending crafting order intercepted in transit. Perhaps you can be the means to its end.",it="Un ordine di creazione in sospeso intercettato durante il trasporto. Forse puoi contribuire a portarlo a compimento."},
