 [3089]={enName="Tome of Flamestrike",en="Teaches Flamestrike (Rank 1).",it="Insegna Colonna di Fuoco (Grado 1)."},
 [3090]={enName="Tome of Frostbolt",en="Teaches Frostbolt (Rank 1).",it="Insegna Dardo di Gelo (Grado 1)."},
 [3091]={enName="Tome of Arcane Intellect II",en="Teaches Arcane Intellect (Rank 2).",it="Insegna Intelletto Arcano (Grado 2)."},
